#[cfg(test)]
mod tests {
    use super::*;

    /// The curated set is exactly the 163 names
    /// (111 original + 52 added in Phase N from the
    /// p13 §3a/Tier B list).
    #[test]
    fn curated_set_has_163_names() {
        assert_eq!(ICON_NAMES.len(), 163, "the curated set is 163 icons");
    }

    /// Every listed name resolves through
    /// `icon_data()` to a sane entry: positive view
    /// box width and a non-empty path that starts
    /// with a moveto, like every Font Awesome glyph.
    #[test]
    fn every_listed_name_resolves() {
        for name in ICON_NAMES {
            let (width, d) = icon_data(name)
                .unwrap_or_else(|| panic!("{name} is listed but has no data"));
            assert!(width > 0.0, "{name} has a non-positive view box width");
            assert!(d.starts_with('M'), "{name} path does not start with M");
        }
    }

    /// An unlisted name resolves to nothing.
    #[test]
    fn unlisted_name_resolves_to_none() {
        assert!(icon_data("definitely-not-an-icon").is_none());
    }
}
